 1	predicate strictNegative(v:array<int>,i:int,j:int)
 2	reads v
 3	requires 0<=i<=j<=v.Length
 4	{forall u | i<=u<j :: v[u]<0}
 5	
 6	predicate positive(s:seq<int>)
 7	{forall u::0<=u<|s| ==> s[u]>=0}
 8	
 9	predicate isPermutation(s:seq<int>, t:seq<int>)
10	{multiset(s)==multiset(t)}
11	
12	/**
13	returns an index st new array is a permutation of the old array
14	positive first and then strictnegative, i is the firs neg or len if not any */
15	method separate(v:array<int>) returns (i:int)
16	modifies v
17	ensures 0<=i<= (v.Length) - 1
18	ensures positive(v[0..i]) && strictNegative(v,i,v.Length)
19	ensures isPermutation(v[0..v.Length], old(v[0..v.Length]))
20	{
21	    i:=0;
22	    var j:=v.Length - 1;
23	    while(i<=j)
24	    decreases j-i
25	    invariant 0<=i<=j+1<=v.Length
26	    invariant strictNegative(v,j+1,v.Length)
27	    invariant positive(v[0..i]) 
28	    invariant isPermutation(v[0..v.Length], old(v[0..v.Length]))
29	    {
30	        if(v[i]>=0){
31	           i:=i+1;
32	        }
33	        else if(v[j]>=0){
34	            assert v[i]<0;
35	            v[i],v[j]:=v[j],v[i];
36	            j:=j-1;
37	
38	            i:=i+1;
39	        }
40	        else if(v[j]<0){
41	            j:=j-1;
42	        }
43	    }
44	    
45	}

